-- 03 — Data model (PostgreSQL 16 + TimescaleDB). This is the first Alembic migration.
-- Conventions: UUIDv7 ids generated by the application; money in integer XOF; times in timestamptz (UTC).

CREATE EXTENSION IF NOT EXISTS timescaledb;
CREATE EXTENSION IF NOT EXISTS citext;

-- ---------- enums ----------
CREATE TYPE user_role        AS ENUM ('owner', 'manager', 'staff', 'installer', 'support');
CREATE TYPE lang_code        AS ENUM ('fr', 'wo', 'en');
CREATE TYPE shop_status      AS ENUM ('draft', 'installing', 'active', 'paused', 'closed');
CREATE TYPE kit_status       AS ENUM ('in_stock', 'assigned', 'installing', 'active', 'retired');
CREATE TYPE kit_health       AS ENUM ('ok', 'degraded', 'offline', 'unknown');
CREATE TYPE camera_role      AS ENUM ('door', 'counter', 'shelf');
CREATE TYPE zone_type        AS ENUM ('door_line', 'customer_side', 'staff_side', 'shelf', 'ignore');
CREATE TYPE event_type       AS ENUM ('entry', 'exit', 'service', 'wait', 'unattended', 'after_hours_motion', 'kit_offline');
CREATE TYPE sale_source      AS ENUM ('wave', 'orange_money', 'quick_log', 'pos', 'cash_declaration');
CREATE TYPE verdict_code     AS ENUM ('learning', 'normal', 'worth_a_look', 'large_gap', 'not_enough_activity', 'incomplete_data');
CREATE TYPE confidence_level AS ENUM ('high', 'medium', 'low');
CREATE TYPE alert_type       AS ENUM ('not_opened', 'unattended', 'after_hours_motion', 'kit_offline');
CREATE TYPE command_type     AS ENUM ('clip', 'snapshot', 'count_check_start', 'count_check_stop', 'update_agent', 'reboot');
CREATE TYPE command_status   AS ENUM ('queued', 'sent', 'done', 'failed', 'unavailable', 'expired');

-- ---------- accounts and people ----------
CREATE TABLE accounts (
    id              uuid PRIMARY KEY,
    name            text NOT NULL,
    plan            text NOT NULL DEFAULT 'pilot',
    language        lang_code NOT NULL DEFAULT 'fr',
    clip_access_for_managers boolean NOT NULL DEFAULT false,
    created_at      timestamptz NOT NULL DEFAULT now(),
    deleted_at      timestamptz
);

CREATE TABLE users (
    id              uuid PRIMARY KEY,
    account_id      uuid REFERENCES accounts(id),          -- NULL for installer/support (Seetlu side)
    name            text NOT NULL,
    phone_e164      text NOT NULL UNIQUE,                    -- also the WhatsApp id
    role            user_role NOT NULL,
    language        lang_code NOT NULL DEFAULT 'fr',
    receives_report boolean NOT NULL DEFAULT false,
    active          boolean NOT NULL DEFAULT true,
    created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON users (account_id);

CREATE TABLE otp_codes (
    id              uuid PRIMARY KEY,
    phone_e164      text NOT NULL,
    code_hash       text NOT NULL,
    expires_at      timestamptz NOT NULL,
    attempts        int NOT NULL DEFAULT 0,
    consumed_at     timestamptz
);
CREATE INDEX ON otp_codes (phone_e164, expires_at);

-- ---------- shops ----------
CREATE TABLE shops (
    id                  uuid PRIMARY KEY,
    account_id          uuid NOT NULL REFERENCES accounts(id),
    name                text NOT NULL,
    category            text NOT NULL,                       -- boutique, superette, pharmacie, quincaillerie, salon, telephonie, other
    address             text,
    gps_lat             numeric(9,6),
    gps_lng             numeric(9,6),
    timezone            text NOT NULL DEFAULT 'Africa/Dakar',
    opening_hours       jsonb NOT NULL,                      -- {"mon":[["08:00","21:00"]], ..., "sun":[]}
    report_time         time NOT NULL DEFAULT '21:00',
    cash_prompt_time    time NOT NULL DEFAULT '20:30',
    quiet_hours         jsonb NOT NULL DEFAULT '{"start":"22:00","end":"07:00"}',
    expected_staff      int NOT NULL DEFAULT 0,
    service_min_s       int NOT NULL DEFAULT 15 CHECK (service_min_s BETWEEN 10 AND 60),
    wait_min_s          int NOT NULL DEFAULT 180,
    unattended_min_s    int NOT NULL DEFAULT 300,
    cdp_declaration_ref text,                                -- required before activation (AC-F8-4)
    status              shop_status NOT NULL DEFAULT 'draft',
    activated_at        timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON shops (account_id);

CREATE TABLE user_shops (
    user_id  uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    shop_id  uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    PRIMARY KEY (user_id, shop_id)
);

-- ---------- kits, cameras, zones ----------
CREATE TABLE kits (
    id                  uuid PRIMARY KEY,
    serial              text NOT NULL UNIQUE,
    claim_token_hash    text NOT NULL,
    device_token_hash   text,                                -- set at activation; agent auth
    shop_id             uuid REFERENCES shops(id),
    installer_id        uuid REFERENCES users(id),
    status              kit_status NOT NULL DEFAULT 'in_stock',
    health              kit_health NOT NULL DEFAULT 'unknown',
    agent_version       text,
    frigate_version     text,
    target_agent_version text,
    config_version      int NOT NULL DEFAULT 1,
    last_seen_at        timestamptz,
    installed_at        timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON kits (shop_id);

CREATE TABLE cameras (
    id                  uuid PRIMARY KEY,
    kit_id              uuid NOT NULL REFERENCES kits(id) ON DELETE CASCADE,
    role                camera_role NOT NULL,
    name                text NOT NULL,                       -- frigate camera name, [a-z0-9-]
    rtsp_main_path      text NOT NULL,                       -- stored without credentials; credentials live on the edge only
    rtsp_sub_path       text NOT NULL,
    detect_width        int NOT NULL DEFAULT 640,
    detect_height       int NOT NULL DEFAULT 360,
    detect_fps          int NOT NULL DEFAULT 5,
    calibration_snapshot_key text,
    UNIQUE (kit_id, name)
);

CREATE TABLE zones (
    id                  uuid PRIMARY KEY,
    camera_id           uuid NOT NULL REFERENCES cameras(id) ON DELETE CASCADE,
    type                zone_type NOT NULL,
    -- normalised coordinates 0..1. door_line: [[x1,y1],[x2,y2]] + inward_normal side; others: polygon
    geometry            jsonb NOT NULL,
    inward_side         text CHECK (inward_side IN ('left', 'right')),   -- door_line only
    created_at          timestamptz NOT NULL DEFAULT now()
);

-- ---------- time-series: events and heartbeats ----------
CREATE TABLE events (
    id                  uuid NOT NULL,                        -- generated on edge (idempotency)
    shop_id             uuid NOT NULL REFERENCES shops(id),
    kit_id              uuid NOT NULL REFERENCES kits(id),
    camera_id           uuid REFERENCES cameras(id),
    type                event_type NOT NULL,
    started_at          timestamptz NOT NULL,
    ended_at            timestamptz,
    duration_s          int GENERATED ALWAYS AS (CASE WHEN ended_at IS NULL THEN NULL ELSE EXTRACT(EPOCH FROM (ended_at - started_at))::int END) STORED,
    is_staff            boolean NOT NULL DEFAULT false,
    confidence          real NOT NULL DEFAULT 1.0,
    frigate_event_ids   text[] NOT NULL DEFAULT '{}',
    meta                jsonb NOT NULL DEFAULT '{}',
    received_at         timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (id, started_at)
);
SELECT create_hypertable('events', 'started_at', chunk_time_interval => interval '7 days');
CREATE INDEX ON events (shop_id, type, started_at DESC);

CREATE TABLE heartbeats (
    kit_id              uuid NOT NULL REFERENCES kits(id),
    at                  timestamptz NOT NULL,
    power_source        text,                                 -- mains | battery
    battery_pct         smallint,
    storage_pct         smallint,
    cpu_temp_c          real,
    fps                 jsonb,                                -- {"door": 5.0, "counter": 4.9}
    network             text,                                 -- wifi | 4g | ethernet
    agent_version       text,
    frigate_version     text,
    queue_depth         int,
    PRIMARY KEY (kit_id, at)
);
SELECT create_hypertable('heartbeats', 'at', chunk_time_interval => interval '7 days');

-- ---------- sales ----------
CREATE TABLE sales (
    id                  uuid PRIMARY KEY,
    shop_id             uuid NOT NULL REFERENCES shops(id),
    source              sale_source NOT NULL,
    amount_xof          bigint NOT NULL CHECK (amount_xof >= 0),
    occurred_at         timestamptz NOT NULL,
    local_date          date NOT NULL,                        -- shop-local day, set by the API
    external_ref        text,                                 -- mobile money transaction id
    entered_by          uuid REFERENCES users(id),
    device_id           uuid,                                 -- phone app install id
    raw_encrypted       bytea,                                -- original notification (encrypted), optional
    created_at          timestamptz NOT NULL DEFAULT now(),
    voided_at           timestamptz,
    UNIQUE (shop_id, source, external_ref)
);
CREATE INDEX ON sales (shop_id, local_date);
-- one cash declaration per shop-day
CREATE UNIQUE INDEX sales_one_cash_decl ON sales (shop_id, local_date) WHERE source = 'cash_declaration' AND voided_at IS NULL;

CREATE TABLE unparsed_notifications (
    id                  uuid PRIMARY KEY,
    shop_id             uuid NOT NULL REFERENCES shops(id),
    package_name        text NOT NULL,
    received_at         timestamptz NOT NULL,
    raw_encrypted       bytea NOT NULL,
    created_at          timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE phone_devices (
    id                  uuid PRIMARY KEY,
    shop_id             uuid NOT NULL REFERENCES shops(id),
    token_hash          text NOT NULL,
    model               text,
    app_version         text,
    parser_version      text,
    last_seen_at        timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now()
);

-- ---------- reports, baselines, corrections ----------
CREATE TABLE daily_reports (
    id                  uuid PRIMARY KEY,
    shop_id             uuid NOT NULL REFERENCES shops(id),
    local_date          date NOT NULL,
    visitors_in         int,
    served              int,
    waits               int,
    unattended_min      int,
    busiest_hour        smallint,
    sales_count         int NOT NULL DEFAULT 0,
    sales_xof           bigint NOT NULL DEFAULT 0,
    sales_by_source     jsonb NOT NULL DEFAULT '{}',          -- {"wave": 45000, "orange_money": 12000, ...}
    cash_declared_xof   bigint,
    rps_xof             numeric(12,2),                        -- revenue per served customer
    baseline            jsonb,                                -- {"rps_median":..,"rps_mad":..,"n_days":..}
    verdict             verdict_code NOT NULL,
    confidence          jsonb NOT NULL DEFAULT '{}',          -- {"visitors_in":"high","served":"medium"}
    missing_hours       smallint[] NOT NULL DEFAULT '{}',
    moments             jsonb NOT NULL DEFAULT '[]',          -- [{"rank":1,"event_id":..,"kind":..,"clip_command_id":..}]
    vs_last_week        jsonb,
    computed_at         timestamptz NOT NULL DEFAULT now(),
    sent_at             timestamptz,
    message_id          text,
    UNIQUE (shop_id, local_date)
);

CREATE TABLE day_corrections (
    id                  uuid PRIMARY KEY,
    shop_id             uuid NOT NULL REFERENCES shops(id),
    local_date          date NOT NULL,
    metric              text NOT NULL CHECK (metric IN ('visitors_in', 'served')),
    reported_value      int,
    corrected_value     int,
    note                text,
    created_by          uuid NOT NULL REFERENCES users(id),
    created_at          timestamptz NOT NULL DEFAULT now()
);

-- ---------- alerts ----------
CREATE TABLE alert_rules (
    id                  uuid PRIMARY KEY,
    shop_id             uuid NOT NULL REFERENCES shops(id),
    type                alert_type NOT NULL,
    enabled             boolean NOT NULL DEFAULT true,
    params              jsonb NOT NULL DEFAULT '{}',          -- not_opened: {"grace_min":30}; unattended: {"min":10}
    UNIQUE (shop_id, type)
);

CREATE TABLE alerts_sent (
    id                  uuid PRIMARY KEY,
    shop_id             uuid NOT NULL REFERENCES shops(id),
    type                alert_type NOT NULL,
    local_date          date NOT NULL,
    event_id            uuid,
    sent_at             timestamptz NOT NULL DEFAULT now(),
    message_id          text
);
CREATE INDEX ON alerts_sent (shop_id, local_date);

-- ---------- edge commands and clips ----------
CREATE TABLE edge_commands (
    id                  uuid PRIMARY KEY,
    kit_id              uuid NOT NULL REFERENCES kits(id),
    type                command_type NOT NULL,
    params              jsonb NOT NULL DEFAULT '{}',          -- clip: {"camera":"counter","start":..,"end":..}
    status              command_status NOT NULL DEFAULT 'queued',
    result              jsonb,
    requested_by        uuid REFERENCES users(id),
    created_at          timestamptz NOT NULL DEFAULT now(),
    expires_at          timestamptz NOT NULL,
    completed_at        timestamptz
);
CREATE INDEX ON edge_commands (kit_id, status);

CREATE TABLE clips (
    id                  uuid PRIMARY KEY,
    shop_id             uuid NOT NULL REFERENCES shops(id),
    event_id            uuid,
    command_id          uuid REFERENCES edge_commands(id),
    object_key          text NOT NULL,
    kind                text NOT NULL CHECK (kind IN ('clip', 'snapshot')),
    duration_s          int,
    size_bytes          bigint,
    saved_by            uuid REFERENCES users(id),
    expires_at          timestamptz,                          -- NULL when saved
    created_at          timestamptz NOT NULL DEFAULT now()
);

-- ---------- count check (installer) ----------
CREATE TABLE count_checks (
    id                  uuid PRIMARY KEY,
    kit_id              uuid NOT NULL REFERENCES kits(id),
    installer_id        uuid NOT NULL REFERENCES users(id),
    started_at          timestamptz NOT NULL,
    ended_at            timestamptz,
    manual_count        int,
    agent_count         int,
    error_pct           numeric(5,2),
    passed              boolean,
    override_reason     text
);

-- ---------- consents, support grants, audit ----------
CREATE TABLE support_grants (
    id                  uuid PRIMARY KEY,
    account_id          uuid NOT NULL REFERENCES accounts(id),
    granted_by          uuid NOT NULL REFERENCES users(id),
    granted_to          uuid REFERENCES users(id),            -- NULL = any support user
    expires_at          timestamptz NOT NULL,
    created_at          timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE audit_log (
    id                  uuid PRIMARY KEY,
    account_id          uuid,
    actor_id            uuid,
    actor_role          user_role,
    action              text NOT NULL,                        -- clip.view, clip.save, zone.update, correction.create, support.access ...
    target_type         text,
    target_id           uuid,
    detail              jsonb NOT NULL DEFAULT '{}',
    at                  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON audit_log (account_id, at DESC);

-- ---------- billing (MVP: manual reconciliation) ----------
CREATE TABLE subscriptions (
    id                  uuid PRIMARY KEY,
    account_id          uuid NOT NULL REFERENCES accounts(id),
    plan                text NOT NULL,
    monthly_service_xof bigint NOT NULL,
    kit_financing_months int NOT NULL DEFAULT 0,
    kit_monthly_xof     bigint NOT NULL DEFAULT 0,
    next_due_date       date NOT NULL,
    status              text NOT NULL DEFAULT 'active',       -- active | overdue | suspended | cancelled
    created_at          timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE payments (
    id                  uuid PRIMARY KEY,
    subscription_id     uuid NOT NULL REFERENCES subscriptions(id),
    amount_xof          bigint NOT NULL,
    method              text NOT NULL,                        -- wave | orange_money | cash
    external_ref        text,
    paid_at             timestamptz NOT NULL,
    recorded_by         uuid REFERENCES users(id)
);
